\label{tab:layer_modes}
\begin{tabular}{lcccc}
\toprule
\textbf{Mode} & \textbf{Spec \%} & \textbf{Ling \%} & \textbf{$\chi^2$} & \textbf{$p$} \\
\midrule
Unauth.\ assumption & 45.3 & 6.0 & 58.2 & $<$0.0001 \\
